 private final Handler h=new Handler(Looper.getMainLooper());private final String session=UUID.randomUUID().toString();private final VideoWatch89 video=new VideoWatch89();private InputModel input=new InputModel(session);private BenchJournal89 journal;private String fatal=null,lastInput="",message="Chưa phát · quyền mock chưa cấp",history="";private boolean foreground=false,focused=false,destroyed=false,watchKeys=false;private long inputEpoch=0;private int keyEvents=0,rawMotion=0;private final ArrayList<Long> keyDelays=new ArrayList<>();private InputManager manager;private MediaPlayer player;private Surface surface;private TextureView texture;private FrameLayout stage;private TextView status,metrics,provenance;private Typeface medium,bold;private long decoderGeneration=-1;private int extractorSamples=0;private long durationUs=0;private JSONObject clip;private LinearLayout root;
 private long now(){return SystemClock.elapsedRealtime();}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private TextView text(String value,int size,boolean strong){TextView t=new TextView(this);t.setText(value);t.setTextColor(strong?0xfff4f5f2:0xffb7c3bc);t.setTextSize(size);t.setTypeface(strong?bold:medium);t.setPadding(dp(8),dp(5),dp(8),dp(5));return t;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894);medium=Typeface.createFromAsset(getAssets(),"Barlow-Medium.ttf");bold=Typeface.createFromAsset(getAssets(),"Barlow-Bold.ttf");try{journal=new BenchJournal89(new File(getFilesDir(),"bench89"),session);}catch(Exception e){fatal="TRACE_UNAVAILABLE_NO_ACCEPTANCE: "+e.getMessage();}layout();manager=(InputManager)getSystemService(INPUT_SERVICE);manager.registerInputDeviceListener(this,h);record("SESSION",object("format","aeris-native89-bench","version",1,"source","SYNTHETIC_FIXTURE","operational",false,"flightAuthority",false,"authorityRestorable",false,"cameraToDisplayLatencyMs",JSONObject.NULL,"sdk",Build.VERSION.SDK_INT,"model",Build.MODEL,"fixtureSha256",BuildInfo89.FIXTURE_SHA,"inputPolicyMs",InputModel.MAX_AGE_MS,"renderCallbackPolicyMs",VideoWatch89.STALE_MS,"clock","ELAPSED_REALTIME_MS_WITH_SEPARATE_UPTIME_KEY_DOMAIN"));h.post(ticker);}
 private JSONObject object(Object...p){JSONObject o=new JSONObject();try{for(int n=0;n<p.length;n+=2)o.put(String.valueOf(p[n]),p[n+1]);}catch(Exception e){throw new IllegalStateException(e);}return o;}
 private JSONObject snapshot(){try{return object("foreground",foreground,"focused",focused,"input",new JSONObject(input.json()),"video",new JSONObject(video.json(now())),"keyEvents",keyEvents,"rawMotionCallbacks",rawMotion,"watchKeys",watchKeys,"flightAuthority",false,"physicalInputVerified",false,"cameraToDisplayLatencyMs",JSONObject.NULL);}catch(Exception e){return object("snapshotUnavailable",e.getClass().getSimpleName(),"flightAuthority",false);}}
 private void record(String kind,JSONObject body){if(journal==null||fatal!=null)return;try{body.put("kind",kind);body.put("session",session);body.put("receiptUptimeMs",SystemClock.uptimeMillis());journal.append(body.toString(),now());}catch(Exception e){fatal="TRACE_BLOCKED_NO_ACCEPTANCE: "+e.getMessage();watchKeys=false;input.focus(false,now());video.stop("TRACE_BLOCKED");release(false);}}
 private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTypeface(bold);b.setTextSize(15);b.setTextColor(0xfff5f5f0);b.setContentDescription(title);b.setMinHeight(dp(56));b.setBackgroundTintList(ColorStateList.valueOf(0xff28322d));b.setOnClickListener(v->{if(fatal!=null){paint();return;}record("UI_ACTION",object("label",title));action.run();paint();});return b;}
 private void row(String[] names,Runnable[] actions){LinearLayout r=new LinearLayout(this);for(int i=0;i<names.length;i++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(62),1);p.setMargins(dp(4),dp(3),dp(4),dp(3));r.addView(button(names[i],actions[i]),p);}root.addView(r);}
 private void layout(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(10),dp(16),dp(10));root.setBackgroundColor(0xff0c1510);setContentView(root);root.addView(text("RtR   /   AERIS                         BENCH 89 · INPUT & VIDEO",23,true));provenance=text("COMPANION CHẨN ĐOÁN · Không nối drone · Không SDK/HeraHub · Clip tổng hợp, không ảnh camera",14,false);root.addView(provenance);status=text(message,16,true);status.setTextColor(0xffedcf58);root.addView(status);
 LinearLayout body=new LinearLayout(this);stage=new FrameLayout(this);stage.setBackgroundColor(0xff050a07);TextView empty=text("VIDEO LAB\n\nBộ giải mã Android\nNguồn clip: synthetic VP8\nTuổi camera / độ trễ camera: chưa biết",22,true);empty.setGravity(Gravity.CENTER);stage.addView(empty,new FrameLayout.LayoutParams(-1,-1));LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,-1,2);left.setMargins(dp(4),dp(6),dp(10),dp(6));body.addView(stage,left);ScrollView scroll=new ScrollView(this);metrics=text("",14,false);metrics.setContentDescription("Thông số bench hiện tại");scroll.addView(metrics);LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,-1,1);right.setMargins(dp(4),dp(6),dp(4),dp(6));body.addView(scroll,right);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
 row(new String[]{"Self-test ART","Phát clip mô phỏng","Phát rồi giữ frame","Dừng video"},new Runnable[]{this::selfTest,()->play(false),()->play(true),()->stop("OPERATOR_STOPPED",false)});
 row(new String[]{"Replay input mock","Thử trục sai","Quan sát phím","Lịch sử phiên"},new Runnable[]{this::replayInput,this::invalidInput,()->{watchKeys=!watchKeys;record("KEY_OBSERVATION",snapshot());},this::history});paint();}
 private void paint(){if(status==null||destroyed)return;String headline=fatal!=null?fatal:message;if(!headline.contentEquals(status.getText()))status.setText(headline);String age="—";try{Long a=video.callbackAge(now());age=a==null?"—":video.playing()?a+" ms":"đã dừng / không live";}catch(Exception ignored){}Long p95=null;if(!keyDelays.isEmpty()){ArrayList<Long>a=new ArrayList<>(keyDelays);Collections.sort(a);p95=a.get((int)Math.ceil(a.size()*.95)-1);}String detail="RENDER CALLBACK\n"+video.state+"\nGeneration "+video.generation+" · callbacks "+video.frames+"\nTuổi callback: "+age+"\nTuổi camera: chưa biết\nĐộ trễ camera → màn hình: chưa biết\n\nINPUT MOCK\n"+input.reason()+"\nAxis "+input.axis()+" · mockOwned "+input.owned()+"\nKhông có quyền bay hoặc transport\n\nANDROID INPUT CALLBACK\nPhím: "+keyEvents+" · motion: "+rawMotion+"\nQuan sát: "+(watchKeys?"BẬT":"TẮT")+"\nKey dispatch p95: "+(p95==null?"chưa đo":p95+" ms")+"\nChỉ uptime trong Android; không độ trễ RC\n\nTRACE\n"+session.substring(0,8)+" · "+(journal==null?"chưa mở":journal.count()+" events")+"\nKhông phục hồi ownership/playback\n"+history;if(!detail.contentEquals(metrics.getText()))metrics.setText(detail);}
 private void selfTest(){try{JSONObject r=new JSONObject(ModelTest89.run());r.put("runtime","ANDROID_ART");record("ART_SELF_TEST",r);message="ART self-test: "+r.getInt("checks")+" PASS · chỉ mô hình mock";}catch(Throwable e){record("ART_SELF_TEST_FAILED",object("error",e.toString()));message="Self-test FAIL · không nghiệm thu";}}
 private void replayInput(){if(!foreground||!focused)return;final long epoch=++inputEpoch;input.attach(ModelTest89.cal(),now());record("MOCK_INPUT_BEGIN",snapshot());for(int i=0;i<3;i++){final int n=i;h.postDelayed(()->{if(epoch!=inputEpoch||!foreground||!focused)return;long t=now();input.sample(session,"mock:bench89",0,t);if(n==2){input.hold(true,t);boolean acquired=input.acquire(t);record("MOCK_ACQUIRED",object("acquired",acquired,"snapshot",snapshot()));message="Đã nhận quyền mock; tự thu hồi khi mẫu hết250ms";}else record("MOCK_NEUTRAL",snapshot());paint();},i*70);}h.postDelayed(()->{if(epoch==inputEpoch&&foreground&&focused){input.sample(session,"mock:bench89",.55,now());record("MOCK_AXIS",snapshot());paint();}},210);}
 private void invalidInput(){if(!foreground||!focused)return;try{input.sample(session,"mock:bench89",2,now());record("INVALID_AXIS_RATE_LIMITED",snapshot());}catch(IllegalArgumentException e){record("INVALID_AXIS_REJECTED",snapshot());message="Trục sai bị chặn · không clamp thành lệnh";}}
 private void inventory()throws Exception{byte[] b;try(InputStream in=getAssets().open("synthetic.webm")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] a=new byte[8192];int n;while((n=in.read(a))!=-1){out.write(a,0,n);if(out.size()>1024*1024)throw new IOException("FIXTURE_CAP");}b=out.toByteArray();}String sha=BenchJournal89.sha(b);if(!BuildInfo89.FIXTURE_SHA.equals(sha))throw new IOException("FIXTURE_SHA");MediaExtractor ex=new MediaExtractor();try(AssetFileDescriptor fd=getAssets().openFd("synthetic.webm")){ex.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());int selected=-1;MediaFormat format=null;for(int i=0;i<ex.getTrackCount();i++){MediaFormat f=ex.getTrackFormat(i);if(f.getString(MediaFormat.KEY_MIME).startsWith("video/")){if(selected>=0)throw new IOException("MULTIPLE_VIDEO_TRACKS");selected=i;format=f;}}if(selected<0||!"video/x-vnd.on2.vp8".equals(format.getString(MediaFormat.KEY_MIME))||format.getInteger(MediaFormat.KEY_WIDTH)!=640||format.getInteger(MediaFormat.KEY_HEIGHT)!=360)throw new IOException("FIXTURE_FORMAT");durationUs=format.getLong(MediaFormat.KEY_DURATION);if(durationUs<=0||durationUs>10000000)throw new IOException("DURATION");ex.selectTrack(selected);int count=0;long last=-1;while(ex.getSampleTime()>=0){long at=ex.getSampleTime();if(at<last||++count>240)throw new IOException("SAMPLE_BOUND_OR_ORDER");last=at;if(!ex.advance())break;}if(count<1)throw new IOException("NO_VIDEO_SAMPLES");extractorSamples=count;clip=object("sha256",sha,"bytes",b.length,"mime","video/x-vnd.on2.vp8","width",640,"height",360,"durationUs",durationUs,"extractorSamples",count,"source","SYNTHETIC_FIXTURE","physicalMediaVerified",false);record("FIXTURE_INVENTORY",new JSONObject(clip.toString()));}finally{ex.release();}}
 private void play(boolean freeze){if(!foreground||!focused)return;try{stop("EXPLICIT_NEW_VIDEO_GENERATION",true);inventory();final long g=video.prepare(now());decoderGeneration=g;final TextureView view=new TextureView(this);texture=view;view.setOpaque(false);view.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture st,int w,int hh){if(view==texture&&g==video.generation)preparePlayer(g,view,freeze);fit(view);}public void onSurfaceTextureSizeChanged(SurfaceTexture st,int w,int hh){fit(view);}public boolean onSurfaceTextureDestroyed(SurfaceTexture st){if(view==texture&&g==video.generation)stop("SURFACE_LOST",true);return true;}public void onSurfaceTextureUpdated(SurfaceTexture st){if(view!=texture||g!=video.generation||player==null)return;long at=now(),pts=st.getTimestamp();boolean accepted=video.frame(g,pts,at);record(accepted?"FRAME_CALLBACK":"REJECTED_FRAME_CALLBACK",object("generation",g,"textureTimestampNs",pts,"snapshot",snapshot()));paint();}});stage.addView(view,new FrameLayout.LayoutParams(-1,-1));message="Chuẩn bị decoder Android · không tự loop";record("VIDEO_PREPARE",object("generation",g,"freezeFault",freeze,"snapshot",snapshot()));}catch(Exception e){stop("VIDEO_PREPARE_ERROR",true);record("VIDEO_ERROR",object("error",e.toString()));message="Decoder không mở được · xem trace";}paint();}
 private void fit(TextureView v){int w=v.getWidth(),hh=v.getHeight();if(w<1||hh<1)return;float fw=Math.min(w,hh*640f/360f),fh=fw*360f/640f;Matrix m=new Matrix();m.setScale(fw/w,fh/hh,w/2f,hh/2f);v.setTransform(m);}
 private void preparePlayer(final long g,final TextureView view,final boolean freeze){try{final MediaPlayer mp=new MediaPlayer();player=mp;surface=new Surface(view.getSurfaceTexture());mp.setSurface(surface);mp.setVolume(0,0);mp.setLooping(false);try(AssetFileDescriptor fd=getAssets().openFd("synthetic.webm")){mp.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());}mp.setOnPreparedListener(v->{if(player!=mp||g!=video.generation||view!=texture||!foreground||!focused)return;if(!video.prepared(g,v.getVideoWidth(),v.getVideoHeight(),v.getDuration(),now())||!video.start(g,now())){stop("VIDEO_METADATA_ERROR",true);return;}record("VIDEO_STARTED",object("generation",g,"metadata",clip,"durationMs",v.getDuration(),"snapshot",snapshot()));v.start();message="Clip tổng hợp đang phát · tuổi camera chưa biết";paint();if(freeze)h.postDelayed(()->{if(player==mp&&g==video.generation&&video.playing()){mp.pause();record("FAULT_PLAYER_PAUSED_RETAIN_FRAME",snapshot());message="Giữ frame có chủ ý · chờ watchdog500ms";paint();}},350);});mp.setOnInfoListener((v,what,extra)->{if(player==mp&&g==video.generation&&what==MediaPlayer.MEDIA_INFO_VIDEO_RENDERING_START)record("RENDER_START",object("generation",g,"notCameraLatency",true));return false;});mp.setOnCompletionListener(v->{if(player!=mp||g!=video.generation)return;boolean proof=video.end(g,now());record("VIDEO_ENDED",object("generation",g,"callbackProof",proof,"snapshot",snapshot()));release(false);message=proof?"Clip kết thúc · có callback decoder · không ảnh camera":"Clip kết thúc nhưng chưa có bằng chứng callback";paint();});mp.setOnErrorListener((v,what,extra)->{if(player==mp&&g==video.generation){record("VIDEO_ERROR",object("generation",g,"what",what,"extra",extra));stop("DECODE_ERROR",true);message="Decoder từ chối clip";paint();}return true;});mp.prepareAsync();}catch(Exception e){record("VIDEO_ERROR",object("error",e.toString()));stop("PLAYER_OPEN_ERROR",true);paint();}}
 private void release(boolean remove){MediaPlayer p=player;player=null;if(p!=null){p.setOnPreparedListener(null);p.setOnCompletionListener(null);p.setOnInfoListener(null);p.setOnErrorListener(null);p.release();}if(surface!=null){surface.release();surface=null;}if(remove&&texture!=null){TextureView t=texture;texture=null;stage.removeView(t);}}
 private void stop(String reason,boolean hide){video.stop(reason);release(hide);record("VIDEO_STOP",object("reason",reason,"snapshot",snapshot()));message="Video dừng · "+reason;}
 private void history(){File dir=new File(getFilesDir(),"bench89");File[] a=dir.listFiles();int count=0;long size=0;if(a!=null)for(File f:a)if(f.getName().endsWith(".jsonl")){count++;size+=f.length();}history="Lịch sử: "+count+" trace / "+size+" bytes\nChỉ dữ liệu; không phục hồi quyền hoặc player";record("HISTORY_INSPECTED",object("traces",count,"bytes",size,"restored",false));}
 private final Runnable ticker=new Runnable(){public void run(){if(destroyed)return;try{input.tick(now());String reason=input.reason();if(!reason.equals(lastInput)){lastInput=reason;record("INPUT_STATE",snapshot());}String before=video.state;video.tick(now());if(!before.equals(video.state)&&video.state.equals("STALLED_NO_AUTO_RESUME")){release(false);message="Frame không cập nhật · đã khóa freshness; phát lại có chủ ý";record("VIDEO_STALE",snapshot());}paint();}catch(Exception e){fatal="CLOCK_OR_MODEL_BLOCKED: "+e.getMessage();release(true);}h.postDelayed(this,50);}};
 @Override public boolean dispatchKeyEvent(KeyEvent e){int k=e.getKeyCode();if(watchKeys&&foreground&&focused&&(k>=19&&k<=22||k==96||k==97)){long receipt=SystemClock.uptimeMillis(),delay=receipt-e.getEventTime();Long measured=delay>=0&&delay<=2000?delay:null;if(measured!=null&&keyDelays.size()<128)keyDelays.add(measured);keyEvents++;record("ANDROID_KEY_UNATTESTED",object("keyCode",k,"action",e.getAction(),"repeat",e.getRepeatCount(),"deviceId",e.getDeviceId(),"source",e.getSource(),"eventUptimeMs",e.getEventTime(),"callbackUptimeMs",receipt,"dispatchDelayMs",measured==null?JSONObject.NULL:measured,"clockDomain","ANDROID_UPTIME_MILLIS","noControlMapping",true));paint();return true;}return super.dispatchKeyEvent(e);}
 @Override public boolean onGenericMotionEvent(MotionEvent e){if(watchKeys&&foreground&&focused&&(e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK&&e.getAction()==MotionEvent.ACTION_MOVE){JSONArray a=new JSONArray();InputDevice d=e.getDevice();if(d!=null)for(InputDevice.MotionRange range:d.getMotionRanges()){if(a.length()>=16)break;a.put(object("axis",range.getAxis(),"raw",e.getAxisValue(range.getAxis())));}rawMotion++;record("ANDROID_JOYSTICK_RAW_UNMAPPED",object("deviceId",e.getDeviceId(),"source",e.getSource(),"axes",a,"physicalMappingVerified",false));paint();return true;}return super.onGenericMotionEvent(e);}
 @Override public void onInputDeviceAdded(int id){record("INPUT_DEVICE_ADDED",object("deviceId",id,"mappingVerified",false));}@Override public void onInputDeviceChanged(int id){inputEpoch++;input.detach(now());record("INPUT_DEVICE_CHANGED",object("deviceId",id,"snapshot",snapshot()));}@Override public void onInputDeviceRemoved(int id){inputEpoch++;input.detach(now());record("INPUT_DEVICE_REMOVED",object("deviceId",id,"snapshot",snapshot()));}
 @Override protected void onResume(){super.onResume();foreground=true;watchKeys=false;record("ACTIVITY_RESUMED_NO_RESTORE",snapshot());message="Phiên chỉ quan sát · chưa phát, chưa có quyền mock";paint();}
 @Override public void onWindowFocusChanged(boolean has){super.onWindowFocusChanged(has);focused=has;inputEpoch++;input.focus(has,now());if(!has){watchKeys=false;stop("FOCUS_LOST",true);}record(has?"FOCUS_GAINED_NO_RESTORE":"FOCUS_LOST",snapshot());paint();}
 @Override protected void onPause(){foreground=false;focused=false;watchKeys=false;inputEpoch++;input.focus(false,now());stop("ANDROID_BACKGROUND",true);record("ACTIVITY_PAUSED",snapshot());super.onPause();}
 @Override protected void onDestroy(){destroyed=true;inputEpoch++;h.removeCallbacksAndMessages(null);video.stop("DESTROYED");release(true);if(manager!=null)manager.unregisterInputDeviceListener(this);record("ACTIVITY_DESTROYED",snapshot());try{if(journal!=null)journal.close();}catch(Exception ignored){}super.onDestroy();}
